//! Golden files generated by the pinned official Python writer/decoder, not by
//! this crate. See fixtures/README.md and scripts/verify-coolchic.py.
#[test]
fn official_reference_fixtures_decode_exactly() {
    for (bytes, expected, width, height) in [
        (
            include_bytes!("fixtures/reference-3x5.cool").as_slice(),
            include_bytes!("fixtures/reference-3x5.rgba").as_slice(),
            3,
            5,
        ),
        (
            include_bytes!("fixtures/reference-13x17.cool").as_slice(),
            include_bytes!("fixtures/reference-13x17.rgba").as_slice(),
            13,
            17,
        ),
    ] {
        let image = coolchic::decode(bytes).unwrap();
        assert_eq!((image.width, image.height), (width, height));
        assert_eq!(image.rgba, expected);
    }
}

#[test]
fn malformed_headers_never_panic() {
    // Exercise bit mutations of every bit in a real reference header/network.
    // A mutation may be another valid stream, but must be bounded and panic-free.
    let original = include_bytes!("fixtures/reference-13x17.cool");
    for p in 0..original.len().min(128) {
        for bit in 0..8 {
            let mut bytes = original.to_vec();
            bytes[p] ^= 1 << bit;
            if coolchic::dimensions(&bytes).is_ok_and(|(w, h)| w <= 64 && h <= 64) {
                let _ = coolchic::decode(&bytes);
            }
        }
    }
}
